def get_color_row_info(input_grid):
    """For each row, find the rightmost column for each color"""
    row_info = {}
    for r, row in enumerate(input_grid):
        color_rightmost = {}
        for c, val in enumerate(row):
            if val != 0:
                if val not in color_rightmost:
                    color_rightmost[val] = c
                else:
                    color_rightmost[val] = max(color_rightmost[val], c)
        row_info[r] = color_rightmost
    return row_info

def compact_by_rightmost_rule(input_grid):
    """Apply the hypothesized rule: within each row, sort colors by rightmost input col, then pack to right"""
    ROW_WIDTH = len(input_grid[0])
    row_info = get_color_row_info(input_grid)

    output_rows = []
    for row in input_grid:
        # Get all non-zero colors in this row
        colors_in_row = []
        for c, val in enumerate(row):
            if val != 0:
                colors_in_row.append(val)

        if not colors_in_row:
            output_rows.append([0] * len(row))
            continue

        # Sort colors by their rightmost position in the input row (ascending = leftmost rightmost first)
        sorted_colors = sorted(list(set(colors_in_row)), 
                              key=lambda c: row_info.get(min(r for ri, ci in positions_by_color(row) if ci) for _, ci in enumerate(row) if val==c if (ri, ci) in positions_by_color(row, val)), 
                              reverse=False)

        # This is getting complicated, let me try simpler approach
        # Actually the rule might be: sort by C order in that row first appearance, then pack to right

        output_row = [0] * ROW_WIDTH
        for color in colors_in_row:
            output_row[color] = color
        output_rows.append(output_row)

    return output_rows

